/* The page, built from the runs in data.js.
 *
 * Three rules this file follows, each learned by getting one of them wrong in this exercise:
 *
 *   1. No number is written in this file. Every figure comes from `M`, generated by
 *      tools/render_results.py from the tracked results/*.json. This exercise already shipped a
 *      document that claimed every figure was generated while fifteen were typed inside the
 *      renderer — and a page is the version of that failure the most people see.
 *   2. A mechanism figure is not a results chart. The shift is the central object here, so the
 *      page draws it: two rows of real token strings, offset by one. Results say what happened;
 *      mechanism says why it must.
 *   3. A failure goes in the opening tiles. A page that shows only its wins has not earned them.
 *
 * Sections carry `data-role`, so the spine is checkable without pinning any wording.
 */

const NS = 'http://www.w3.org/2000/svg';
const main = () => document.getElementById('main');

function el(tag, cls, text) {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (text !== undefined) n.textContent = text;
  return n;
}

function svg(tag, attrs = {}) {
  const n = document.createElementNS(NS, tag);
  for (const [k, v] of Object.entries(attrs)) n.setAttribute(k, String(v));
  return n;
}

function svgText(x, y, cls, text) {
  const t = svg('text', { x, y, class: cls });
  t.textContent = text;
  return t;
}

let sectionCount = 0;

/** A section whose eyebrow names its epistemic role, so a reader knows how to weigh it. */
function section(id, role, eyebrow, title, paras, rail) {
  const s = el('section');
  s.id = id;
  s.dataset.role = role;
  sectionCount += 1;
  s.dataset.n = String(sectionCount);
  s.dataset.title = (rail && rail.short) || title;
  if (rail && rail.sub) s.dataset.sub = rail.sub;
  s.append(el('p', 'role', eyebrow), el('h2', null, title));
  for (const p of [].concat(paras || [])) {
    const n = el('p', 'say');
    n.innerHTML = p;
    s.append(n);
  }
  main().append(s);
  return s;
}

let figureCount = 0;

/** A figure whose caption says what to conclude — never a bare label.
 *
 * **The number is counted, not passed.** It used to be an argument, and adding the ship figure at
 * the top of the page gave the page two Figure 1s — the new one and the mechanism plate, both
 * captioned "Figure 1", in the same document. A figure's number is a count of the figures before
 * it, which makes it exactly the kind of number this page derives everywhere else.
 */
function figure(node, caption) {
  figureCount += 1;
  const f = el('figure');
  f.append(node);
  const c = el('figcaption');
  c.innerHTML = `<b>Figure ${figureCount}.</b> ${caption}`;
  f.append(c);
  return f;
}

function table(head, rows, cls) {
  const wrap = el('div', 'tablewrap');
  const t = el('table', cls || 'grid');
  const thead = el('thead');
  const hr = el('tr');
  for (const h of head) {
    const th = el('th');
    th.innerHTML = h;
    hr.append(th);
  }
  thead.append(hr);
  t.append(thead);
  const tb = el('tbody');
  for (const row of rows) {
    const tr = el('tr');
    if (row.__mark) tr.className = row.__mark;
    for (const cell of row.cells) {
      const td = el('td');
      td.innerHTML = cell === null || cell === undefined ? '—' : cell;
      tr.append(td);
    }
    tb.append(tr);
  }
  t.append(tb);
  wrap.append(t);
  return wrap;
}

/* Counts are SPELLED from the data, never typed. A heading or a rail label that states a number
 * is stating a count of its own contents, so typing it is how a page comes to read "Three commands"
 * over four of them and "Nine words, each with a number" over four words — both of which this page
 * shipped. Ported from exercise 08, which introduced the helper for the same reason. */
const SPELLED = [
  'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten',
  'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen',
  'nineteen', 'twenty',
];
const spell = (n) => SPELLED[n] || String(n);
const Spell = (n) => {
  const w = spell(n);
  return w[0].toUpperCase() + w.slice(1);
};

const int = (n) => Math.round(n).toLocaleString('en-US');
const signed = (n, d = 4) => (n >= 0 ? '+' : '−') + Math.abs(n).toFixed(d);
const pct = (n, d = 1) => `${(n * 100).toFixed(d)}%`;
const mib = (bytes) => (bytes / (1024 * 1024)).toFixed(1);

/* How many decimals a measurement's own noise floor will support.
 *
 * **This page stated its precision rule and then broke it four times.** The results section says the
 * memory ratio is "quoted as about 9x and no finer" — and the opening tile said 9.1x, the glossary
 * said 9.1x, the ledger said 9.09x and the conclusion said 9.09x, one of them fourteen lines above
 * the rule. Every one of those was a `toFixed()` chosen at the call site, so the rule was a sentence
 * and the practice was five independent decisions.
 *
 * Deriving the precision from the spread makes the page unable to break it. A spread of 0.44 cannot
 * support a tenth, so the digit is not offered.
 */
const decimalsFor = (spread) => (spread >= 0.5 ? 0 : spread >= 0.05 ? 1 : 2);

/** A ratio quoted to the precision its own repeated measurement earns, never finer. */
const ratio = (value, spread) => `${value.toFixed(decimalsFor(spread))}×`;

/* ============================================================== 1 · thesis */

function chapterThesis(M) {
  const t = M.training.summary;
  const b = M.boundary;
  const s = section(
    'thesis',
    'thesis',
    'Two runs, one question',
    'Which of these would you ship?',
    [
      `Below are the loss curves of two models. Same architecture, same data, same seed, same
       ${int(t.total_steps)} steps. One of them is broken — its target shift is off by one, so it is
       being handed its own input as the answer and is learning to copy. <b>Pick the one you would
       ship, before scrolling.</b>`,
      `Almost everyone picks by the number going down, because that is how a training run is
       normally judged. It is also the only judgement this particular bug is invisible to.`,
    ],
    { short: 'The curve', sub: 'pick a run before you scroll' }
  );

  s.append(shipExplainer(M));

  const lesson = el('p', 'say');
  lesson.innerHTML = `<b>The point survives whether or not you played.</b> A lower loss is not
    evidence of a better model; it is evidence that the model found an easier question. Copying is
    easier than predicting, so the broken run reaches
    <b>${t.final_broken_shift.toFixed(2)}</b> while the correct one is still at
    <b>${t.final_correct_shift.toFixed(2)}</b> — and the only reliable check is to print the inputs
    and targets as text and read them, which is what the next section does.`;
  s.append(lesson);

  const tiles = el('div', 'tiles');
  for (const [v, k, mark] of [
    [
      t.final_broken_shift.toFixed(2),
      `the loss a <b>broken</b> model reaches, against ${t.final_correct_shift.toFixed(2)} for the
       correct one. It is counting copies, not predictions`,
      'watch',
    ],
    [
      int(b.boundary_crossings),
      `document boundary crossed in the packed example. <b>This page published
       ${int(b.mask_dropped_including_padding)}</b> until it was checked — that figure counts every
       pair the mask touches, most of them padding`,
      'bad',
    ],
    [
      ratio(M.memory.ratio, M.sensitivity.memory.spread),
      `less memory for an identical loss — but only because the projection happens inside the loop.
       Chunking the softmax alone, which is what the name usually means, is worth
       ${ratio(M.memory.softmax_only_ratio, M.sensitivity.memory.spread)}`,
      'watch',
    ],
    [
      pct(M.heads.head_share),
      `of this model is the output head — of head plus an <i>estimated</i> body. Against the trunk
       actually built it is ${pct(M.shapes.trunk_params ? M.heads.untied_params / (M.heads.untied_params + M.shapes.trunk_params) : 0)}`,
      'watch',
    ],
  ]) {
    const tile = el('div', `tile ${mark}`);
    const value = el('div', 'tile-v');
    value.innerHTML = v;
    const key = el('div', 'tile-k');
    key.innerHTML = k;
    tile.append(value, key);
    tiles.append(tile);
  }
  s.append(tiles);

  const note = el('p', 'say');
  note.innerHTML = `<b>Read those ${spell(4)} tiles as one sentence: check what the number is
    counting.</b> They are marked alike because they <i>are</i> alike — the red one is the only one
    this page published wrong, and none of the others is good news. Two of them are failures and one of the failures is ours, published on this page
    for weeks. That is the thread every section below is on — a loss counting copies, a count of
    dropped positions that counted the wrong positions, a memory ratio that belongs to a different
    technique than the one it is usually quoted for, and a percentage measured against a body
    nobody built. None of them is a bug in the arithmetic. All of them are a bug in the question.`;
  s.append(note);
}

/* -------------------------------------------------------- the one interaction on this page
 *
 * Family: Diff (EXPLAINER_PROMPT §10) — "these look equivalent and are not", inverted: they look
 * clearly UNequal and the obvious winner is the broken one. It is spent on the thesis rather than
 * on a widget because the page's whole claim is that the reader's default judgement is wrong, and
 * the cheapest way to establish that is to let them make it.
 *
 * The shape is docs/EXPLAINER_PATTERN.md §4 — pure `stateFor`, render-only `show`, a `guard` for
 * the state it cannot answer in. It does NOT vendor `_shared/explainer.js`: that skeleton is a
 * scrollytelling topology (states down the left, one pinned figure), and this is a single binary
 * choice. Borrowing it would mean building eleven states to hold one question.
 */
function shipExplainer(M) {
  /* 1. CONSTANTS — the two curves, from the run. Nothing here is typed. */
  const A = M.training.correctShift;
  const B = M.training.brokenShift;
  const steps = M.training.steps;
  const pairs = { correct: M.shift.correct_pairs, broken: M.shift.broken_pairs };

  /* 2. PURE HELPERS. */
  const lo = Math.min(...A, ...B);
  const hi = Math.max(...A, ...B);
  const W = 720;
  const H = 260;
  const PAD = { l: 46, r: 118, t: 18, b: 30 };
  const px = (i) => PAD.l + (i / (steps.length - 1)) * (W - PAD.l - PAD.r);
  const py = (v) => PAD.t + (1 - (v - lo) / (hi - lo || 1)) * (H - PAD.t - PAD.b);
  const path = (series) => series.map((v, i) => `${i ? 'L' : 'M'}${px(i)},${py(v)}`).join(' ');

  /* 3. STATE — the minimum that cannot be derived. */
  let chosen = null; // null | 'correct' | 'broken'

  const wrap = el('div', 'ship');

  const chart = svg('svg', {
    viewBox: `0 0 ${W} ${H}`,
    class: 'ship-chart',
    role: 'img',
    'aria-label': 'two training loss curves, unlabelled until a choice is made',
  });
  for (const [v, label] of [
    [hi, hi.toFixed(1)],
    [lo, lo.toFixed(1)],
  ]) {
    chart.append(svg('line', { x1: PAD.l, x2: W - PAD.r, y1: py(v), y2: py(v), class: 'ship-grid' }));
    chart.append(svgText(PAD.l - 8, py(v) + 4, 'ax', label));
  }
  chart.append(svgText(PAD.l - 8, py((lo + hi) / 2) + 4, 'ax mid', 'loss'));
  const lineA = svg('path', { d: path(A), class: 'ship-line a' });
  const lineB = svg('path', { d: path(B), class: 'ship-line b' });
  chart.append(lineA, lineB);
  const tagA = svgText(px(steps.length - 1) + 6, py(A[A.length - 1]) + 4, 'ship-tag a', 'A');
  const tagB = svgText(px(steps.length - 1) + 6, py(B[B.length - 1]) - 6, 'ship-tag b', 'B');
  tagA.setAttribute('text-anchor', 'start');
  tagB.setAttribute('text-anchor', 'start');
  chart.append(tagA, tagB);
  chart.append(svgText(PAD.l, H - 8, 'ax', '0'));
  chart.append(svgText(W - PAD.r - 34, H - 8, 'ax end', `${int(steps.length)} steps`));

  const controls = el('div', 'ship-controls');
  const ask = el('div', 'ship-ask', 'Which run would you ship?');
  const buttons = el('div', 'ship-btns');
  const btnA = el('button', 'ship-btn', 'Ship A');
  const btnB = el('button', 'ship-btn', 'Ship B');
  btnA.type = 'button';
  btnB.type = 'button';
  buttons.append(btnA, btnB);
  controls.append(ask, buttons);

  const verdict = el('div', 'ship-verdict');
  const readout = el('div', 'ship-read');

  /* guard() — the precondition. Before a choice there is no verdict to render, and rendering one
   * anyway is how a widget comes to answer a question nobody asked. */
  const guard = () => (chosen === null ? { note: 'Nothing is labelled yet. Pick one.' } : null);

  /* stateFor(pick) — PURE. Choice → everything the renderer needs. No DOM. */
  const stateFor = (pick) => {
    const shipped = pick === 'broken' ? 'B' : 'A';
    return {
      shipped,
      right: pick === 'correct',
      finalA: A[A.length - 1],
      finalB: B[B.length - 1],
      rows: pairs[pick].slice(0, 5),
      other: pick === 'correct' ? 'broken' : 'correct',
    };
  };

  /* show(pick) — RENDER ONLY. */
  const show = (pick) => {
    chosen = pick;
    btnA.classList.toggle('on', pick === 'correct');
    btnB.classList.toggle('on', pick === 'broken');
    const refused = guard();
    if (refused) {
      verdict.textContent = refused.note;
      verdict.className = 'ship-verdict';
      readout.replaceChildren();
      return;
    }
    const st = stateFor(pick);
    wrap.classList.add('revealed');
    tagA.textContent = 'A · correct shift';
    tagB.textContent = 'B · off by one';
    verdict.className = `ship-verdict ${st.right ? 'good' : 'bad'}`;
    verdict.innerHTML = st.right
      ? `<b>A is the correct model</b> — and it is the one with the <i>higher</i> loss, at
         ${st.finalA.toFixed(2)} against ${st.finalB.toFixed(2)}. If you picked it, you picked
         against the number.`
      : `<b>B is the broken model.</b> Its loss is lower — ${st.finalB.toFixed(2)} against
         ${st.finalA.toFixed(2)} — because it is not predicting anything. Here is what it was
         actually asked:`;

    const rows = st.rows.map((pair) => ({ cells: [`<code>${pair[0]}</code>`, `<code>${pair[1]}</code>`] }));
    readout.replaceChildren(
      table(
        [`given this token`, `predict this one — <b>${pick === 'correct' ? 'A' : 'B'}</b>`],
        rows,
        'grid tight'
      )
    );
    const foot = el('p', 'say small');
    foot.innerHTML =
      pick === 'correct'
        ? `That is a prediction: every target is the token that actually came next. Switch to B to
           see what the broken run was asked instead.`
        : `Every target is the token already in the input. The model is being graded on copying,
           which is why the curve looks like a triumph. Switch to A for the real task.`;
    readout.append(foot);
  };

  /* Three ways in — pointer, keyboard focus, and the print path. A reader who never clicks still
   * gets the labelled chart, because `playAll` forces the end state. */
  btnA.addEventListener('click', () => show('correct'));
  btnB.addEventListener('click', () => show('broken'));
  btnA.addEventListener('focus', () => {
    if (chosen === null) ask.classList.add('nudge');
  });
  wrap.playAll = () => show('broken');

  wrap.append(chart, controls, verdict, readout);
  show(null);
  return figure(
    wrap,
    `<b>Neither curve is labelled, and that is the argument.</b> Everything a training dashboard
     shows you about these two runs is on this figure already; if that is enough to tell them apart,
     this page has nothing to say. <b>What would refute it:</b> a broken run whose curve sat
     <i>above</i> the correct one. Then watching the number would be a sufficient check, which is
     exactly what most people believe it is.`
  );
}

/* ============================================================== 2 · glossary */

function chapterGlossary(M) {
  const c = M.config;
  /* The entries are built BEFORE the section, so the heading can count them. A heading that states
   * a number is stating a count of its own contents; typing it is how this page came to say "Eight
   * words" over a list that had grown. */
  const entries = [
    [
      'token',
      `A piece of text the model treats as one unit — often a word, often part of one. This page uses
       the tokenizer from exercise 02, which has ${int(c.vocab_size - 1)} of them.`,
    ],
    [
      'the loss',
      `One number saying how wrong the model's guesses were, averaged over the positions that count.
       Lower is better, and training is the process of making it smaller. A fresh model here scores
       ${M.perplexity.loss.toFixed(4)}.`,
    ],
    [
      'logits',
      `The raw score the model gives every token in the vocabulary, before any of them is turned into
       a probability. One per token, per position: a
       <code>${M.shapes.shapes[2][1].join(' × ')}</code> block for a single batch.`,
    ],
    [
      'the output head',
      `The final layer, turning the model's ${c.d_model}-number thought at each position into one
       score per token. It is <b>${int(M.heads.untied_params)}</b> numbers here — the one matrix in
       the model sized by the tokenizer rather than by the model.`,
    ],
    [
      'tying',
      `Reusing the input word list as the output head, instead of buying a second copy. It costs
       <b>${M.heads.tied_params}</b> extra parameters against
       <b>${int(M.heads.untied_params)}</b> for an untied head, and forces a token's input vector
       and its scoring direction to be the same thing.`,
    ],
    [
      'padding',
      `Filler added to short sequences so a batch is rectangular. It is not a prediction. In the
       example below, ${int(M.padding.dropped)} of ${int(M.padding.positions_before)} positions are
       padding — ${pct(M.padding.dropped / M.padding.positions_before, 0)} of the batch.`,
    ],
    [
      'masking',
      `Excluding positions from the loss. The mask is not the interesting part; the
       <b>contributing count</b> is, because a loss that moved tells you nothing until you know
       whether the set of positions under it moved too. In the padded example below it takes
       ${int(M.padding.positions_before)} positions down to
       <b>${int(M.padding.positions_after)}</b>.`,
    ],
    [
      'perplexity',
      `The loss read as a count: the size of the uniform menu the model behaves as though it were
       choosing from. This model starts at <b>${int(M.perplexity.perplexity)}</b> against a
       vocabulary of ${int(c.vocab_size)}.`,
    ],
    [
      'nats',
      `The unit every loss on this page is in — the natural-log version of bits. Nothing here is
       ever converted, so a gap of <b>${Math.abs(M.training.summary.gap).toFixed(2)}</b> between two
       heads means ${Math.abs(M.training.summary.gap).toFixed(2)} nats and never anything else.`,
    ],
    [
      'the trunk',
      `Everything before the output head: the ${c.n_layer} transformer blocks that turn tokens into
       a ${c.d_model}-number thought per position. <b>${int(M.shapes.trunk_params)}</b> parameters
       here, and it produces no scores at all — that is the head's job, which is why the two are
       priced separately.`,
    ],
    [
      'chunking',
      `Computing the loss a few hundred rows at a time instead of all at once. Which few hundred is
       the whole question: chunk the softmax over logits that already exist and you save the
       intermediates; project <i>inside</i> the loop and the full score tensor never exists, which
       is worth <b>${ratio(M.memory.ratio, M.sensitivity.memory.spread)}</b> here.`,
    ],
    [
      'packing',
      `Putting several documents end to end in one sequence so no row is mostly padding. It creates
       the one thing the loss must then be told to ignore: the <b>join</b> — at position
       ${int(M.boundary.join_position)} in the example below, and the source of the single crossing
       position section 7 costs at ${M.boundary.crossing_loss.toFixed(2)}.`,
    ],
    [
      'the projection',
      `The matmul from the model's ${c.d_model}-number thought to one score per token — the step that
       creates the ${int(M.shapes.shapes[2][1][0] * M.shapes.shapes[2][1][1])}-row scores tensor.
       Where it happens decides the memory: outside a loop the whole tensor exists at once, inside
       one it never does, and that is the difference between the two figures in section 7.`,
    ],
    [
      '▁ (the underscore)',
      `Not a character in the text. The tokenizer writes a leading space this way, so
       <code>▁of</code> is " of" and <code>of</code> is the "of" inside another word. It opens
       <b>${M.shift.correct_pairs.filter((pair) => pair[0].startsWith('▁')).length}</b> of the
       ${int(M.shift.correct_pairs.length)} tokens in the sequence the figures below draw, and is the
       single most confusing thing about reading tokens as strings.`,
    ],
  ];

  const s = section(
    'glossary',
    'glossary',
    'Before anything else',
    `${Spell(entries.length)} words you need, each carrying a number from this run`,
    [
      `Read this once and nothing below is jargon. Every entry carries a real figure from the runs
       on this page rather than a textbook gloss. <b>Every entry below carries a number</b>, which is
       a promise a test can keep; the page used to promise instead that every word in the tiles above
       was defined here, and that was false twice — first for <b>head</b>, <b>logits</b>,
       <b>output head</b> and <b>tokenizer</b>, and then, after those were added, for <b>packed</b>
       and <b>projection</b>. Both are entries now. The claim is gone because nothing could check
       it, and an unfalsifiable promise on a page about checking things is worse than no promise.`,
    ],
    { short: 'The words', sub: `${spell(entries.length)} terms, with our own figures` }
  );

  const dl = el('dl', 'gloss');
  for (const [term, def] of entries) {
    dl.append(el('dt', null, term));
    const dd = el('dd');
    dd.innerHTML = def;
    dl.append(dd);
  }
  s.append(dl);
}

/* ============================================================== 3 · the problem */

function chapterProblem(M) {
  const rows = problemRows(M);
  const s = section(
    'problem',
    'problem',
    'Three lines, four ways to be wrong',
    'The slice that manufactures every answer',
    [
      `Nobody labelled this text. The right answer is simply the next token, so the whole training
       signal is created by a slice. Three lines of code do it — and every one of the
       ${spell(rows.length)} failures below lives inside them.`,
      `<b>None raises an exception. Two of them make the loss look better.</b> That is what makes
       them expensive: they do not announce themselves, and the metric you would use to catch them
       is the metric they improve.`,
    ],
    { short: 'The slice', sub: `${spell(rows.length)} silent failures` }
  );

  s.append(table(['what goes wrong', 'why it is silent', 'what you would see'], rows, 'grid prose'));
  problemTail(M, s);
}

/** The four failures, as data, so the section that introduces them can count them. */
function problemRows(M) {
  return [
    {
      cells: [
        '<b>The shift goes the wrong way</b>',
        'The model is handed its own input as the answer and learns to copy.',
        `<span class="worse">loss falls to ${M.shift.loss_off_by_one ? M.training.summary.final_broken_shift.toFixed(2) : '—'}</span>`,
      ],
      __mark: 'bad',
    },
    {
      cells: [
        '<b>Padding is counted</b>',
        'Filler is trivially predictable, so scoring it rewards the model for nothing.',
        '<span class="worse">loss improves</span>',
      ],
      __mark: 'bad',
    },
    {
      cells: [
        '<b>A packed boundary is predicted across</b>',
        'Two documents joined in one sequence: the gradient asserts a continuation that does not exist.',
        'loss barely moves',
      ],
    },
    {
      cells: [
        '<b>The mean uses the wrong denominator</b>',
        'Dividing by every position rather than the ones that counted scales each batch by how much of it was real.',
        'loss drifts batch to batch',
      ],
    },
  ];
}

/** The paragraph that follows the table, kept beside it rather than inside the row data. */
function problemTail(M, s) {
  const note = el('p', 'say');
  note.innerHTML = `The third and fourth are the ones this exercise got wrong <i>while building the
    page you are reading</i> — the boundary mask kept every pair of padding positions, and a chunked
    loss divided by the wrong count. Both are in <a href="#negatives">the corrections</a>.`;
  s.append(note);
}

/* ============================================================== 4 · mechanism */

function shiftFigure(M) {
  const pairs = M.shift.correct_pairs;
  const broken = M.shift.broken_pairs;
  const n = Math.min(pairs.length, 7);

  /* Cell width is derived from the longest string the figure actually has to hold, not guessed.
   * The first version used a fixed 92px and the token text spilled out of five of seven boxes —
   * which no test caught, because `scrollWidth`/`clientWidth` mean nothing on an SVG <text> and a
   * viewBox check only sees the figure's outer edge. */
  const longest = Math.max(
    ...pairs.slice(0, n).flat().map((s) => s.length),
    ...broken.slice(0, n).flat().map((s) => s.length)
  );
  const cell = Math.max(76, longest * 9 + 26);
  const gap = 8;
  const pad = 18;
  const width = pad * 2 + cell * n;
  const node = svg('svg', {
    viewBox: `0 0 ${width} 348`,
    class: 'fig shiftfig',
    role: 'img',
    'aria-label':
      'Two rows of token strings offset by one, then the same rows with the broken shift, where ' +
      'every token is asked to predict itself',
  });

  const row = (y, items, cls) =>
    items.forEach((text, i) => {
      const x = pad + i * cell;
      node.append(svg('rect', { x, y, width: cell - gap, height: 34, rx: 6, class: `tok ${cls}` }));
      node.append(svgText(x + (cell - gap) / 2, y + 22, 'tok-t', text));
    });

  const label = (y, text) => node.append(svgText(pad, y, 'fig-lab', text));

  const inputs = pairs.slice(0, n).map((p) => p[0]);
  const targets = pairs.slice(0, n).map((p) => p[1]);

  /* The label sits ABOVE where the arrows start, not across them. The first version put it at the
   * midpoint of the gap and the arrows ran straight through the words. */
  label(24, 'correct — the model reads');
  row(34, inputs, 'tok-in');
  label(96, '…and must predict');
  row(130, targets, 'tok-out');

  /* The arrow runs straight down its own column: `targets[i]` is what `inputs[i]` must predict.
   * The offset lives in the DATA — targets is the sequence shifted by one — not in the geometry,
   * and an arrow drawn diagonally would say something the code does not do. */
  for (let i = 0; i < n; i += 1) {
    const x = pad + i * cell + (cell - gap) / 2;
    node.append(svg('path', { d: `M ${x} 106 L ${x} 126`, class: 'lead', 'marker-end': 'url(#arrow)' }));
  }

  const defs = svg('defs');
  const marker = svg('marker', {
    id: 'arrow',
    viewBox: '0 0 8 8',
    refX: 7,
    refY: 4,
    markerWidth: 5,
    markerHeight: 5,
    orient: 'auto',
  });
  marker.append(svg('path', { d: 'M 0 0 L 8 4 L 0 8 z', class: 'arrowhead' }));
  defs.append(marker);
  node.append(defs);

  node.append(
    svg('line', { x1: pad, x2: width - pad, y1: 196, y2: 196, class: 'fig-divide' })
  );

  label(226, 'the off-by-one — the model reads');
  row(236, broken.slice(0, n).map((p) => p[0]), 'tok-in');
  label(298, '…and must predict ITSELF');
  row(306, broken.slice(0, n).map((p) => p[1]), 'tok-bad');

  return node;
}


function chapterMechanism(M) {
  const s = section(
    'mechanism',
    'mechanism',
    'The central object, drawn',
    'Where a target actually comes from',
    [
      `A sequence of <i>T</i> tokens gives <i>T−1</i> supervised pairs at no cost: drop the last
       position, because nothing follows it; drop the first token, because nothing predicts it.
       Everything the model ever learns comes from that offset.`,
      `<b>Which is why an offset in the wrong direction is so expensive.</b> The bottom row of the
       figure is what the broken version asks for — and read as ids rather than as text, it is
       indistinguishable from the correct one.`,
    ],
    { short: 'The shift', sub: 'inputs, targets, and the off-by-one' }
  );

  s.append(
    figure(
      shiftFigure(M),
      `Above the rule: each box is a token the model reads, and the arrow points at what it must
       predict. Below it: <b>the same reading, with the shift reversed</b> — and every arrow would
       now point at the box it started from. <b>Every pair in the bottom half is a token predicting
       itself.</b> That is the entire bug. It is obvious in text and invisible in integers, which is
       why the check is to print the strings. A single pair down there that differed would mean the
       shift was correct after all.`
    )
  );

  /* **All three, because the page is titled after them.** It showed two — the slice — and never
   * wrote the third or named it, so the headline count was the one number on the page a reader
   * could not check against anything. The third is the line that turns the pair into a scalar, and
   * it is where the padding, the boundary mask and the denominator all live. */
  const code = el('pre', 'code');
  code.textContent =
    'inputs  = tokens[:, :-1]        # drop the last: nothing follows it\n' +
    'targets = tokens[:,  1:]        # drop the first: nothing predicts it\n' +
    'loss    = cross_entropy(logits, targets, ignore_index=-100)';
  s.append(code);

  const which = el('p', 'say');
  which.innerHTML = `<b>Those are the three lines, and one failure lives in each of the first two
    while two live in the third.</b> The slice can go the wrong way. It can also be the right way
    and still hand the loss padding to score. And the third line decides <i>which positions count</i>
    — so a mask that keeps the wrong ones, and a mean over the wrong denominator, are both
    <code>cross_entropy</code>'s arguments rather than anything you would see in a shape.`;
  s.append(which);
}

