/* ============================================================== 7 · results */

function curveFigure(M) {
  const correct = M.training.correctShift;
  const broken = M.training.brokenShift;
  const steps = M.training.steps;
  const w = 720;
  const h = 300;
  const padL = 46;
  const padB = 34;
  const padT = 16;
  const padR = 14;

  const all = correct.concat(broken);
  const hi = Math.max(...all);
  const lo = Math.min(...all);
  const x = (i) => padL + (i / (steps.length - 1)) * (w - padL - padR);
  const y = (v) => padT + ((hi - v) / (hi - lo)) * (h - padT - padB);

  const node = svg('svg', {
    viewBox: `0 0 ${w} ${h}`,
    class: 'fig curvefig',
    role: 'img',
    'aria-label':
      'Two training curves. The correctly shifted model levels off while the mis-shifted one falls far below it.',
  });

  for (let g = 0; g <= 4; g += 1) {
    const v = lo + ((hi - lo) * g) / 4;
    node.append(
      svg('line', { x1: padL, x2: w - padR, y1: y(v), y2: y(v), class: 'gridline' }),
      svgText(padL - 8, y(v) + 4, 'axis end', v.toFixed(1))
    );
  }
  node.append(svgText(padL, h - 8, 'axis', 'step 1'));
  node.append(svgText(w - padR, h - 8, 'axis end', `step ${int(steps[steps.length - 1])}`));

  const path = (series, cls) => {
    const d = series.map((v, i) => `${i ? 'L' : 'M'} ${x(i).toFixed(1)} ${y(v).toFixed(1)}`).join(' ');
    node.append(svg('path', { d, class: cls }));
  };
  path(correct, 'curve-correct');
  path(broken, 'curve-broken');

  /* Labels sit where the two curves are furthest apart and are offset AWAY from each other, not
   * at the last point with a 10px nudge — which put "correct shift" straight through its own
   * line. The gap is widest around two-thirds along, which is also where neither label can reach
   * the other curve. */
  const at = Math.floor(steps.length * 0.62);
  node.append(
    svgText(x(at), y(correct[at]) - 16, 'curve-lab correct', 'correct shift'),
    svgText(x(at), y(broken[at]) + 26, 'curve-lab broken', 'off-by-one')
  );
  return node;
}

